R={'rideId':'RIDE_CAR_001','quote':'Q-CAR-0007','version':1,'pickup':'123 Nguyễn Văn Linh, Hải Châu, Đà Nẵng','dropoff':'Sân bay Đà Nẵng','driver':'Nguyễn Văn Hùng','vehicle':'Toyota Vios','plate':'43A-567.89','fare':42000}
F={'draftId':'CART-014','orderId':'DG123456','version':1,'shop':'Bún Bò Huế O Cô','items':125000,'delivery':25000,'payable':150000,'driverPay':20000,'cashReconcile':130000,'driver':'Trần Minh Anh','plate':'43H1-123.45'}
M=m.money
state_list=[]

def pill(msg,kind='orange'):return f'<span class="pill {kind}">{html.escape(str(msg))}</span>'
def rw(key,val):return f'<div class="row between mt8"><span class="small muted">{key}</span><b>{val}</b></div>'
def sec(title,x,kind=''):return m.card(title,x,kind)
def mark(symbol,kind,title,desc):return f'<div class="stateIcon {kind}">{symbol}</div><div class="stateLead">{title}</div><p class="stateBody">{desc}</p>'
def note(msg,kind='amber'):return f'<div class="notice {kind}">{msg}</div>'
def cta(label,secondary=None):return m.bigfooter(label,secondary=secondary)
def progress_steps(entries):return '<div class="card"><div class="miniStep">'+''.join(f'<span class="{style}">{text}</span>' for text,style in entries)+'</div></div>'
def skeleton():return '<div class="skeleton">' + ''.join(f'<div class="ghost" style="width:{w}%;height:{h}px"></div>' for w,h in [(78,16),(91,12),(61,12)])+'</div>'
def route():return sec('Hành trình đang chọn',f'<div class="trip"><div class="stop"><div class="label">Điểm đón</div><b class="small">{R["pickup"]}</b></div><div class="stop"><div class="label">Điểm đến</div><b class="small">{R["dropoff"]}</b></div></div>')
def fare():return sec('Giá của báo giá đang sử dụng',rw('Mã báo giá',R['quote'])+rw('Giá đề xuất',f'<span class="money med">{M(R["fare"])}</span>')+rw('Phiên báo giá',f'v{R["version"]}'),'purple')
def food():return sec('Đơn hàng đang xử lý',rw('Mã đơn', '#'+F['orderId'])+rw('Cửa hàng',F['shop'])+rw('Tiền món',M(F['items']))+rw('Phí giao',M(F['delivery']))+rw('Khách thanh toán COD',f'<span class="money med">{M(F["payable"])}</span>'),'purple')
def make(base,key,title,icon,kind,lead,desc,sections,primary=None,secondary=None,domain='general',trigger='',next_event='',safe='',severity='P1'):
 slug=base+'__'+key
 body=mark(icon,kind,lead,desc)+sections
 htmlsrc=m.render(slug,title,body,cta(primary,secondary) if primary else None,sub='DealGo · Biến thể trạng thái',action=None)
 # ensure HTML uses same predictable relative asset paths
 (S/(slug+'.html')).write_text(htmlsrc,encoding='utf8')
 state_list.append({'variant_id':slug,'route_id':base,'state':key,'title':title,'domain':domain,'severity':severity,'trigger':trigger,'primary_action':primary or '', 'secondary_action':secondary or '', 'next_event':next_event,'safety_rule':safe})

